package com.orderflow.operations.security;
import static org.assertj.core.api.Assertions.assertThat;import java.time.Instant;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.security.oauth2.jwt.Jwt;
class RequiredJwtClaimsValidatorTest{@Test void requiresJtiRolesAndTokenVersion(){Instant now=Instant.now();Jwt valid=Jwt.withTokenValue("x").header("alg","RS256").subject("user").claim("jti","jti").issuedAt(now).expiresAt(now.plusSeconds(60)).claim("roles",List.of("ADMIN")).claim("token_version",1).build();assertThat(new RequiredJwtClaimsValidator().validate(valid).hasErrors()).isFalse();Jwt invalid=Jwt.withTokenValue("x").header("alg","RS256").subject("user").issuedAt(now).expiresAt(now.plusSeconds(60)).build();assertThat(new RequiredJwtClaimsValidator().validate(invalid).hasErrors()).isTrue();}}
